// ---------------------------------------------------------------------------
// Geometry
// ---------------------------------------------------------------------------

export interface Vec2 {
  x: number;
  z: number;
}

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

export interface RGB {
  r: number;
  g: number;
  b: number;
}

export const vec3 = (x = 0, y = 0, z = 0): Vec3 => ({ x, y, z });
export const vec2 = (x = 0, z = 0): Vec2 => ({ x, z });

export const clamp = (v: number, lo: number, hi: number): number => (v < lo ? lo : v > hi ? hi : v);
export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

export const smoothstep = (edge0: number, edge1: number, x: number): number => {
  const t = clamp((x - edge0) / (edge1 - edge0 || 1e-6), 0, 1);
  return t * t * (3 - 2 * t);
};

/** Shortest signed angular difference from `a` to `b`, in (-PI, PI]. */
export function angleDelta(a: number, b: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

/** Horizontal distance, ignoring height. */
export const distXZ = (a: Vec3, b: Vec3): number => Math.hypot(a.x - b.x, a.z - b.z);

// ---------------------------------------------------------------------------
// Deterministic randomness — terrain, scatter and screenshots must reproduce exactly.
// ---------------------------------------------------------------------------

export interface Rng {
  /** Uniform in [0, 1). */
  next(): number;
  /** Uniform integer in [min, max]. */
  int(min: number, max: number): number;
  /** Uniform in [min, max). */
  range(min: number, max: number): number;
  pick<T>(items: readonly T[]): T;
}

export function makeRng(seed: number): Rng {
  let s = (seed >>> 0) || 0x9e3779b9;
  const next = (): number => {
    s ^= s << 13;
    s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;
    s >>>= 0;
    return s / 0x100000000;
  };
  return {
    next,
    int: (min, max) => Math.floor(min + next() * (max - min + 1)),
    range: (min, max) => min + next() * (max - min),
    pick: <T,>(items: readonly T[]): T =>
      items[Math.floor(next() * items.length) % items.length] as T,
  };
}

// ---------------------------------------------------------------------------
// World
// ---------------------------------------------------------------------------

export type ZoneId = 'hearth' | 'pinewind' | 'reach' | 'kettles' | 'hamlet' | 'ridge' | 'peak';

export const ZONE_IDS: readonly ZoneId[] = [
  'hearth',
  'pinewind',
  'reach',
  'kettles',
  'hamlet',
  'ridge',
  'peak',
] as const;

export type SurfaceKind = 'snow' | 'deep-snow' | 'ice' | 'rock' | 'path' | 'spring' | 'wood';

export interface ZoneDef {
  id: ZoneId;
  /** Centre of the zone's influence disc, world units. */
  centre: Vec2;
  /** Influence radius, world units. */
  radius: number;
  /** Elevation band [low, high] the generator aims for. */
  elevation: [number, number];
  /** The surface dominating here, subject to slope overrides. */
  surfaceBias: SurfaceKind;
  /** Snow-drifting weight 0..1; drives scatter density. */
  snowDensity: number;
}

export interface Heightfield {
  /** Square world extent, centred on the origin. Valid coords are +/- size/2. */
  readonly size: number;
  /** Samples per side. */
  readonly res: number;
  /** Row-major, res * res samples. Read-only by convention. */
  readonly heights: Float32Array;
  heightAt(x: number, z: number): number;
}

export interface TerrainSample {
  height: number;
  /** 0 = flat, 1 = vertical. Equals `1 - normal.y`. */
  slope: number;
  surface: SurfaceKind;
  zone: ZoneId;
}

export interface TerrainSampler {
  readonly size: number;
  heightAt(x: number, z: number): number;
  normalAt(x: number, z: number): Vec3;
  sampleAt(x: number, z: number): TerrainSample;
}

// ---------------------------------------------------------------------------
// Player
// ---------------------------------------------------------------------------

export type MoveMode = 'ground' | 'air' | 'glide' | 'climb' | 'mantle' | 'sled';

export interface PlayerAbilities {
  sprint: boolean;
  sled: boolean;
  lantern: boolean;
}

export interface InputFrame {
  /** Camera-space strafe axis, -1..1. */
  moveX: number;
  /** Camera-space forward axis, -1..1 (+1 = away from camera). */
  moveZ: number;
  jumpPressed: boolean;
  jumpHeld: boolean;
  sprintHeld: boolean;
  interactPressed: boolean;
  /** The interact key is down this frame: a throw is drawn while it is held and flies on release. */
  interactHeld: boolean;
  cancelPressed: boolean;
  /** Manual look axis, -1..1 (the look keys held, core/keys.ts; +1 turns the view right). The rig turns at its own rate. */
  lookX: number;
  /** Camera yaw in radians: rotates camera-space input into world space. */
  camYaw: number;
}

export const emptyInput = (camYaw = 0): InputFrame => ({
  moveX: 0,
  moveZ: 0,
  jumpPressed: false,
  jumpHeld: false,
  sprintHeld: false,
  interactPressed: false,
  interactHeld: false,
  cancelPressed: false,
  lookX: 0,
  camYaw,
});

export interface PlayerState {
  pos: Vec3;
  vel: Vec3;
  mode: MoveMode;
  stamina: number;
  maxStamina: number;
  /** Facing yaw in radians. 0 = +Z. */
  facing: number;
  grounded: boolean;
  /** Wing flaps used since last touching ground; reset on landing. */
  flapsUsed: number;
  /** True while standing in a hot spring. */
  soaking: boolean;
  /** Seconds since stamina was last spent; drives the regen delay. */
  sinceSpend: number;
  /** Grace window after leaving the ground where a jump still works. */
  coyote: number;
  /** Remembers a jump pressed just before landing. */
  jumpBuffer: number;
  /** Seconds remaining of the mantle animation. Cosmetic; the mesh layer reads it. */
  mantleTimer: number;
}

export function createPlayerState(spawn: Vec3, maxStamina: number): PlayerState {
  return {
    pos: { ...spawn },
    vel: vec3(),
    mode: 'air',
    stamina: maxStamina,
    maxStamina,
    facing: 0,
    grounded: false,
    flapsUsed: 0,
    soaking: false,
    sinceSpend: 99,
    coyote: 0,
    jumpBuffer: 0,
    mantleTimer: 0,
  };
}

export interface PlayerTuning {
  walkSpeed: number;
  sprintSpeed: number;
  /** Seconds to reach full ground speed. */
  groundAccelTime: number;
  /** Seconds to stop from full ground speed. */
  groundDecelTime: number;
  /** Air acceleration as a fraction of ground acceleration. */
  airControl: number;
  frictionIce: number;
  gravityRise: number;
  gravityFall: number;
  jumpSpeed: number;
  flapSpeed: number;
  drainJump: number;
  flapForward: number;
  /** Holding jump longer than this while airborne becomes a glide rather than a flap. */
  glideHoldThreshold: number;
  glideFallSpeed: number;
  glideDrift: number;
  climbSpeed: number;
  /** Compared against TerrainSample.slope, which is `1 - normal.y`. */
  climbMaxSlope: number;
  mantleReach: number;
  mantleDuration: number;
  coyoteTime: number;
  jumpBufferTime: number;
  staminaMaxBase: number;
  drainFlap: number;
  drainClimb: number;
  drainSprint: number;
  regenIdle: number;
  regenMoving: number;
  regenSoak: number;
  regenDelay: number;
  /** Stamina always regenerates to at least this fraction of max, even in a gust. */
  staminaFloorRatio: number;
  stepHeight: number;
  sledSpeed: number;
  sledSteer: number;
  /** Extra downhill acceleration above 25 degrees of slope, units/s^2. */
  downhillBias: number;
}

export interface PlayerEnvironment {
  terrain: TerrainSampler;
  abilities: PlayerAbilities;
  /** True while a wind gust is active; suppresses regen above the floor. */
  gusting: boolean;
}

export interface PlayerStepResult {
  events: GameEvent[];
  zoneChanged: boolean;
  landed: boolean;
  /** True on the frame stamina first hits zero. */
  exhausted: boolean;
}

/** dt is clamped to this; longer frames are split into substeps to prevent tunnelling. */
export const MAX_STEP_DT = 1 / 30;

/**
 * Advance the player one frame. MUTATES `state` in place and returns what happened.
 * Must be pure with respect to everything else: no DOM, no three, no globals, no Math.random.
 */
export type StepPlayer = (
  state: PlayerState,
  input: InputFrame,
  dt: number,
  tuning: PlayerTuning,
  env: PlayerEnvironment,
) => PlayerStepResult;

// ---------------------------------------------------------------------------
// Conditions & content
// ---------------------------------------------------------------------------

export type ConditionKind =
  | 'talked'
  | 'hasItem'
  | 'visited'
  | 'count'
  | 'activity'
  | 'flag'
  | 'achievement'
  | 'quest'
  | 'reached';

export interface Condition {
  kind: ConditionKind;
  /**
   * NPC id, item id, zone id, counter key, activity id, flag name, quest id (`quest` = complete), or
   * place id (`reached` = Pip has stood at a spot named in data/places.ts, not just entered its zone).
   */
  id: string;
  /** For `count`: required value. Defaults to 1. */
  n?: number;
  /**
   * For `visited`: a hop by the map counts as arriving. Off, only a walk in does ("walk as far as the
   * pines"); on, the thing is carried there however Pip goes ("carry the bundle to the springs").
   */
  hop?: boolean;
}

export interface QuestStep {
  id: string;
  /** Player-facing and short. Shown in the journal. */
  text: string;
  /**
   * `talked` and `visited` count only when they happen while this step is the current one (the engine
   * baselines them as the step begins): "ask Pell" means a new conversation, "take the letter to
   * Hearth Hollow" a walk made carrying it. `activity` and `reached` are credited however long ago
   * they happened, so a snowman built before the step asked for one counts, unless `fresh` is set.
   * Every other kind is a plain fact about state.
   */
  when: Condition;
  /**
   * Only an `activity` or `reached` done while this step is current counts: the errand really means
   * doing it now ("fish the hole while Margit counts"), not having done it once.
   */
  fresh?: true;
  /**
   * The conversation that passes this step also offers that quest, and hearing it accepts it as an
   * offer would. The step's `say` node leads into the quest's `offer` node by `next`. This is how a
   * favour is handed over at the moment it is on the way: Bram gives Tuck's rope with the batteries.
   */
  offers?: string;
  /** Dialogue node the talked-to NPC speaks when this conversation is the one that passes the step. */
  say?: string;
  /**
   * What the same NPC says if talked to again while the quest is still waiting on a later step: the
   * reminder ("the pile still isn't straight") instead of an idle line that forgets what they asked.
   */
  hold?: string;
  /** Handed to the player the moment the step passes. */
  gives?: { item: string; n?: number };
}

export type AbilityId = 'sprint' | 'sled' | 'lantern';

export interface QuestReward {
  feathers?: number;
  bells?: number;
  item?: string;
  itemCount?: number;
  ability?: AbilityId;
  achievement?: string;
}

export type QuestStatus = 'locked' | 'available' | 'active' | 'complete';

export interface QuestDef {
  id: string;
  title: string;
  giver: string;
  zone: ZoneId;
  steps: QuestStep[];
  reward: QuestReward;
  /** Handed to the player the moment the quest is accepted: the thing the errand is about. */
  gives?: { item: string; n?: number };
  requires?: Condition[];
  blurb: string;
  /** Node the giver opens with when offering this quest. Talking accepts it. */
  offer: string;
  /** Node the giver speaks while this quest is running and the talk passed nothing. */
  waiting: string;
  /**
   * Node the giver speaks instead of `waiting` when Pip talks to them again without having walked
   * away since: `waiting` is written for a return ("You're back."), and right after the offer it is
   * false. Absent, `waiting` is used either way.
   */
  still?: string;
  /** Node the giver speaks while this quest is still locked: met too early in the story. */
  notYet?: string;
  /** Quest started automatically the moment this one completes: the main story chains this way. */
  then?: string;
  /** Part of the main story: the goal line and the compass follow it before anything else. */
  main?: boolean;
}

export interface DialogueChoice {
  text: string;
  next: string;
  showIf?: Condition;
  /** Picking this answer takes on the errand on offer: Pip has said yes, so it is not asked again. */
  takes?: boolean;
}

export interface DialogueNode {
  id: string;
  /** NPC id, or 'pip'. */
  speaker: string;
  lines: string[];
  choices?: DialogueChoice[];
  next?: string;
  /**
   * Lines said before `lines`, chosen at run time from what the player has done (src/data/
   * dialogueFills.ts names the sources). The written lines always follow, so a run with nothing to
   * add still reads.
   */
  fill?: string;
}

export interface NpcDef {
  id: string;
  name: string;
  species: string;
  zone: ZoneId;
  pos: Vec2;
  yaw: number;
  /** Node spoken when there is nothing to offer, nothing running and nothing just done. */
  idle: string;
  body: string;
  accent: string;
  radius?: number;
  /** Clothes beyond the scarf (game/world/npcWear.ts): for villagers who share a species with someone. */
  wear?: readonly NpcWear[];
}

export type NpcWear = 'apron' | 'neck-bell' | 'flat-cap';

export interface AchievementDef {
  id: string;
  name: string;
  desc: string;
  /** 12x12 inline SVG path data, single stroke colour. */
  icon: string;
  trigger: Condition;
  hidden?: boolean;
}

export interface ItemDef {
  id: string;
  name: string;
  desc: string;
  icon: string;
  /**
   * Once this holds, the thing has been handed on and is no longer carried. Items stay in the save (a
   * quest may still ask whether Pip ever had them); Field Notes stops listing them. Critic round 11 saw
   * "Carrying: Spare Batteries" after Edda had them in her set.
   */
  handedOver?: Condition;
}

export type FishRarity = 'common' | 'uncommon' | 'rare';

export interface FishDef {
  id: string;
  name: string;
  rarity: FishRarity;
  /** Bells awarded. */
  value: number;
  body: string;
  accent: string;
}

// ---------------------------------------------------------------------------
// Events — discriminated union with typed payloads, plus a drainable queue so a listener
// cannot miss an event emitted before it subscribed.
// ---------------------------------------------------------------------------

export type RewardTier = 'pickup' | 'discovery' | 'milestone' | 'finale';

export interface GameEventPayloads {
  'feather:collected': { id: string; total: number };
  'bell:collected': { n: number };
  /** `byMap`: arrived by a hop from the map, which is a visit but not a walk (session/travel.ts). */
  'zone:entered': { id: ZoneId; byMap?: boolean };
  'quest:started': { id: string };
  'quest:completed': { id: string };
  'fish:caught': { id: string; isNew: boolean };
  'photo:taken': { id: string; isNew: boolean };
  'lantern:lit': { id: string; lit: number };
  /** `bonus` is the run's ActivityResult bonus, such as 'pond-crossed' for a full skating lap. */
  'activity:completed': { id: string; score: number; bonus?: string };
  'achievement:unlocked': { id: string };
  'spring:soaked': { id: string };
  'summit:reached': { id: string };
  /** Pip stepped inside a named place (data/places.ts); fired on each arrival, not every frame. */
  'place:reached': { id: string };
  'item:gained': { id: string; n: number };
  'npc:talked': { id: string };
  toast: { text: string; icon: string; tier: RewardTier };
}

export type GameEventName = keyof GameEventPayloads;

export type GameEvent = {
  [K in GameEventName]: { name: K; data: GameEventPayloads[K] };
}[GameEventName];

export type EventListener = (e: GameEvent) => void;

export interface EventBus {
  emit<K extends GameEventName>(name: K, data: GameEventPayloads[K]): void;
  on(name: GameEventName | '*', fn: EventListener): () => void;
  /** Returns and clears the events accumulated since the last drain. */
  drain(): GameEvent[];
}

// ---------------------------------------------------------------------------
// Interactions — owned by the Gameplay Engineer (src/game/interactions.ts)
// ---------------------------------------------------------------------------

export type InteractableKind = 'npc' | 'activity' | 'lantern' | 'sign' | 'spring' | 'pickup' | 'seat';

export interface Interactable {
  kind: InteractableKind;
  id: string;
  pos: Vec3;
  radius: number;
  /** e.g. "Talk", "Fish", "Light". */
  prompt: string;
  /** Where the prompt pill stands, when that is not `pos`: an activity's start prop. */
  anchor?: Vec3;
  /** Where E puts Pip before acting, when the reach is not where the thing is done from. */
  standAt?: Vec3;
}

export interface InteractionTarget {
  current: Interactable | null;
}

// ---------------------------------------------------------------------------
// Activities (minigames)
// ---------------------------------------------------------------------------

export type ActivityKind = 'fish' | 'photo' | 'sled' | 'skate' | 'throw' | 'build' | 'race';

export interface ActivityDef {
  id: string;
  name: string;
  kind: ActivityKind;
  zone: ZoneId;
  pos: Vec2;
  radius: number;
  prompt: string;
  /** What Pip does there, lower case, for the line that names it nearby: "build a stone dam". */
  what?: string;
}

export interface ActivityResult {
  score: number;
  /** Optional named outcome, e.g. a fish id or 'gold'. */
  bonus?: string;
  itemId?: string;
}

export interface ActivityHost {
  readonly state: Readonly<GameState>;
  readonly terrain: TerrainSampler;
  readonly playerPos: Vec3;
  readonly input: InputFrame;
  readonly cameraYaw: number;
  /** The heading the screen shows: an activity's side shot while one is framed, else `cameraYaw`. */
  readonly viewYaw?: number;
  emit<K extends GameEventName>(name: K, data: GameEventPayloads[K]): void;
  /** Record a finished attempt; the world layer routes the reward. */
  award(result: ActivityResult): void;
}

/**
 * What an activity wants the player told right now. Presented by the activity HUD; activities that
 * have nothing useful to say simply omit `progress()`.
 */
export interface ActivityReadout {
  /** One line of live state, e.g. "2 / 3 placed". */
  label: string;
  /** 0..1, or null when the activity has no notion of progress. */
  fraction: number | null;
  /** True when the player must act this instant; the HUD lights up. */
  urgent?: boolean;
  /**
   * A word or two for the instant itself ("Now! Press F"), drawn large in the middle of the view as well.
   * Critic round 32 missed timing cues that only lit the small panel in the corner, eyes on the world.
   */
  cue?: string;
}

/**
 * A thing the player must be able to SEE during an activity.
 *
 * Added because the photo subject, the throw targets, the fishing float and the build parts existed
 * only as numbers: nothing drew them, so those activities were played blind. Positions are in world
 * space; the renderer owns the meshes.
 */
export type MarkerShape = 'ring' | 'post' | 'float' | 'lump';

export interface MarkerSpec {
  shape: MarkerShape;
  x: number;
  y: number;
  z: number;
  /** 0..1. Full-strength markers are live; dim ones are placed but not yet actionable. */
  strength?: number;
}

export interface ActivityInstance {
  readonly def: ActivityDef;
  /**
   * True when the player must keep control of their own movement for the activity to make sense.
   *
   * Activities normally take the input away and drive themselves. A race cannot: it was measuring a
   * virtual runner while the player's body was frozen, so holding W filled a progress bar without
   * moving anyone. Free-roam activities leave the controller alone and read `host.playerPos`.
   */
  readonly freeRoam?: boolean;
  start(host: ActivityHost): void;
  update(dt: number, host: ActivityHost): void;
  isComplete(): boolean;
  result(): ActivityResult | null;
  abort(): void;
  /**
   * Live presentation state. Added because 22 activities ran with no on-screen feedback at all:
   * the player could not tell a snowball counter from a fishing strike window, and 19 of them were
   * only completable by guessing.
   */
  progress?(): ActivityReadout | null;
  /** World-space markers to draw this frame. */
  markers?(): readonly MarkerSpec[];
  /**
   * A first-person view the activity wants instead of the chase camera, or null for the usual one.
   *
   * Added for the photo viewfinder: the game is keyboard-only and movement is held during an
   * activity, so the chase camera could never be turned onto a subject. The activity owns its aim
   * (read from its own input) and the session hands it to the camera rig each frame. Yaw follows the
   * movement convention (forward = (sin yaw, cos yaw)); pitch is radians above the horizon.
   * `centred` lets the frame overlay light its centre mark without re-deriving the subject.
   */
  view?(): { yaw: number; pitch: number; centred?: boolean } | null;
  /**
   * Where the compass strip should point while this runs, or null to leave it on the goal. Critic round
   * 10 lost the race's next gate behind the pines; the strip now points at it, with its distance.
   */
  compassTarget?(): Vec2 | null;
}

// ---------------------------------------------------------------------------
// Persistent state
// ---------------------------------------------------------------------------

export interface QuestProgress {
  status: QuestStatus;
  /** Index into `QuestDef.steps`. */
  step: number;
  /**
   * The current step's measure (talks with its NPC, entries into its zone, runs of its activity) when
   * the step began. The step passes only once the measure rises above it, so nothing done before the
   * step was current can complete it.
   */
  base?: number;
}

/** Only what is safe to resume from. Never mid-air velocity or a transient mode. */
export interface SavedPlayer {
  pos: Vec3;
  facing: number;
  stamina: number;
}

export interface GameState {
  version: number;
  player: SavedPlayer;
  abilities: PlayerAbilities;
  feathers: number;
  bells: number;
  items: Record<string, number>;
  counters: Record<string, number>;
  flags: Record<string, boolean>;
  talked: Record<string, boolean>;
  /** How many times each NPC has been spoken to: the measure behind a quest's `talked` steps. */
  talkedAt: Record<string, number>;
  visited: Record<string, boolean>;
  quests: Record<string, QuestProgress>;
  achievements: Record<string, number>;
  fish: Record<string, number>;
  photos: Record<string, number>;
  lanterns: Record<string, number>;
  /** Best time in seconds per sled course id. Never a rank or a medal. */
  sledBests: Record<string, number>;
  playtime: number;
  zone: ZoneId;
  checkpoint: Vec3;
  /**
   * True once the opening script (docs/ONBOARDING.md) has run to the end or been skipped.
   *
   * Bumps nothing: a save written before these fields existed belongs to a player who has already
   * played, so `load` falls back to `true` for it and only a genuinely new run sees the prompts.
   */
  onboardingDone: boolean;
  /**
   * The beat the opening script is waiting on, so quitting mid-script resumes there instead of starting
   * at "W A S D — walk" again. A plain string: `core/progress/save.ts` validates the shape, and an id
   * this build does not know restarts the script rather than throwing.
   */
  onboardingBeat: string | null;
}

/**
 * 3: quest steps are baselined as they begin (`QuestProgress.base`) and the main story was rebuilt
 * around new quest ids, so a v2 save would resume into steps that no longer exist. `load` rejects it
 * and the player starts a clean run.
 */
export const SAVE_VERSION = 3;

export function createGameState(spawn: Vec3, maxStamina: number): GameState {
  return {
    version: SAVE_VERSION,
    player: { pos: { ...spawn }, facing: 0, stamina: maxStamina },
    // Sprint starts true. It was `false` and no QuestReward anywhere ever granted it, so Shift did
    // nothing for the whole game while the pause menu advertised the verb (QA D3). Gating basic
    // movement behind a quest punishes the exploring this game is entirely made of.
    abilities: { sprint: true, sled: false, lantern: false },
    feathers: 0,
    bells: 0,
    items: {},
    counters: {},
    flags: {},
    talked: {},
    talkedAt: {},
    visited: {},
    quests: {},
    achievements: {},
    fish: {},
    photos: {},
    lanterns: {},
    sledBests: {},
    playtime: 0,
    zone: 'hearth',
    checkpoint: { ...spawn },
    onboardingDone: false,
    onboardingBeat: null,
  };
}

// ---------------------------------------------------------------------------
// Palette grading — pure math, implemented in core/palette.ts (Director-owned)
// ---------------------------------------------------------------------------

export interface GradeSettings {
  /** 0..1 how far blacks are lifted toward `shadowFloor`. */
  lift: number;
  shadowFloor: [number, number, number];
  saturation: number;
  hueShift: number;
  /** Warm/cool split-toning strength, 0..1. */
  splitTonality: number;
}
